@import url('https://fonts.googleapis.com/css2?family=Montserrat:wght@400;600;700&family=Playfair+Display:ital,wght@0,700;1,700&display=swap');

/* ============================================================
   KUSMI TEA – BUBBLE TEA 300×250 AD
   Palette: #C8102E #F7C548 #1A1A1A #FFFFFF
            #FF6F61 #E91E63 #F9A03F #8BC34A #C8A2C8 #F4E4D4
   ============================================================ */

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #F4E4D4;
  font-family: "Montserrat", sans-serif;
}

/* ── IAB wrapper ─────────────────────────────────────────── */
#ad-300x250 {
  width: 300px;
  height: 250px;
  position: relative;
  overflow: hidden;
  background: #FFFFFF;
  cursor: pointer;
}

/* animated gradient background */
#ad-300x250::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    135deg,
    rgba(244,228,212,0.95) 0%,
    rgba(249,160,63,0.18) 55%,
    rgba(200,16,46,0.10) 100%
  );
  z-index: 0;
  animation: bgShift 6s ease-in-out infinite alternate;
}

@keyframes bgShift {
  0%   { opacity: 0.85; }
  100% { opacity: 1; }
}

/* ── Decorative bubbles ──────────────────────────────────── */

@keyframes floatBubble {
  0%   { transform: translateY(0) scale(1); }
  100% { transform: translateY(-8px) scale(1.06); }
}

/* ── Header ─────────────────────────────────────────────── */
.ad-header {
  position: absolute;
  top: 10px;
  left: 12px;
  right: 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  z-index: 10;
}

.logo {
  height: 28px;
  width: auto;
  display: block;
  /* no filter — logo on light background */
}

.eyebrow {
  font-family: "Montserrat", sans-serif;
  font-weight: 700;
  font-size: 8px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #FFFFFF;
  background: #C8102E;
  padding: 3px 7px;
  border-radius: 20px;
  animation: popIn 0.6s cubic-bezier(0.34,1.56,0.64,1) 0.4s both;
}

@keyframes popIn {
  0%   { transform: scale(0.5); opacity: 0; }
  100% { transform: scale(1);   opacity: 1; }
}

/* ── Product hero ────────────────────────────────────────── */
.product-hero {
  position: absolute;
  right: -10px;
  top: 28px;
  width: 155px;
  height: 155px;
  z-index: 8;
  animation: heroSlide 0.7s cubic-bezier(0.22,1,0.36,1) 0.2s both;
}

@keyframes heroSlide {
  0%   { transform: translateX(40px) scale(0.88); opacity: 0; }
  100% { transform: translateX(0)  scale(1);    opacity: 1; }
}

.product-img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  object-position: center;
  filter: drop-shadow(0 8px 18px rgba(200,16,46,0.18)) drop-shadow(0 2px 6px rgba(26,26,26,0.12));
  transition: transform 0.35s ease;
}

#ad-300x250:hover .product-img {
  transform: scale(1.06) rotate(-2deg);
}

/* ── Copy block ──────────────────────────────────────────── */
.copy-block {
  position: absolute;
  left: 12px;
  top: 44px;
  width: 148px;
  z-index: 10;
  animation: copyFade 0.6s ease 0.5s both;
}

@keyframes copyFade {
  0%   { transform: translateY(10px); opacity: 0; }
  100% { transform: translateY(0);    opacity: 1; }
}

.headline {
  font-family: "Playfair Display", sans-serif;
  font-weight: 700;
  font-size: 20px;
  line-height: 1.15;
  color: #1A1A1A;
  margin-bottom: 4px;
}

.headline em {
  font-style: italic;
  color: #C8102E;
}

.subhead {
  font-family: "Montserrat", sans-serif;
  font-weight: 600;
  font-size: 10px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #F9A03F;
  margin-bottom: 6px;
}

.body-copy {
  font-family: "Montserrat", sans-serif;
  font-weight: 400;
  font-size: 9px;
  line-height: 1.45;
  color: #1A1A1A;
  opacity: 0.82;
  max-width: 130px;
}

/* ── CTA ─────────────────────────────────────────────────── */
.cta-wrap {
  position: absolute;
  left: 12px;
  bottom: 30px;
  z-index: 10;
  animation: ctaBounce 0.5s cubic-bezier(0.34,1.56,0.64,1) 0.9s both;
}

@keyframes ctaBounce {
  0%   { transform: scale(0.7); opacity: 0; }
  100% { transform: scale(1);   opacity: 1; }
}

.cta-btn {
  display: inline-block;
  background: #C8102E;
  color: #FFFFFF;
  text-decoration: none;
  border-radius: 20px;
  padding: 8px 16px;
  transition: background 0.25s ease, transform 0.2s ease, box-shadow 0.25s ease;
  box-shadow: 0 4px 14px rgba(200,16,46,0.35);
}

.cta-btn:hover {
  background: #F9A03F;
  transform: translateY(-2px) scale(1.04);
  box-shadow: 0 6px 18px rgba(249,160,63,0.45);
}

.cta-btn:active {
  transform: translateY(0) scale(0.97);
}

.cta-label {
  font-family: "Montserrat", sans-serif;
  font-weight: 700;
  font-size: 9px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  white-space: nowrap;
}

/* ── Footer ──────────────────────────────────────────────── */
.ad-footer {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 20px;
  background: rgba(26,26,26,0.88);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
}

.ad-footer span {
  font-family: "Montserrat", sans-serif;
  font-weight: 400;
  font-size: 7px;
  letter-spacing: 0.06em;
  color: rgba(255,255,255,0.75);
  text-transform: uppercase;
}

/* ── Accent stripe ───────────────────────────────────────── */
#ad-300x250 .accent-stripe {
  position: absolute;
  left: 0;
  top: 0;
  width: 4px;
  height: 100%;
  background: #F7C548;
  z-index: 5;
}

/* ── Reduced motion ──────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  .bubble,
  .product-img,
  .cta-btn,
  #ad-300x250::after,
  .eyebrow,
  .product-hero,
  .copy-block,
  .cta-wrap {
    animation: none !important;
    transition: none !important;
  }
}

